-- Enlace ACN solo con contexto: Chronorace publica el X2O Badkamers Trofee en contextos con fecha
-- (`20261115_x2o`, árbol generic/uci con tablas RESnn) sin evento ACN público. La rama 'acn' admite
-- "eventId" NULL cuando el contexto lleva fecha AAAAMMDD_<serie>; el resto de proveedores no cambia.
-- cx_ingest_results ya compara evidence.acn.eventId con IS DISTINCT FROM, que admite NULL.
ALTER TABLE public.cx_race_timing_links DROP CONSTRAINT cx_race_timing_links_source_check;
ALTER TABLE public.cx_race_timing_links ADD CONSTRAINT cx_race_timing_links_source_check CHECK ((((provider = 'acn'::text) AND (ctx ~ '^[A-Za-z0-9_.-]{3,80}$'::text) AND ("sourceUrl" IS NULL) AND (("eventId" ~ '^[1-9][0-9]{5,19}$'::text) OR (("eventId" IS NULL) AND (ctx ~ '^[0-9]{8}_[a-z0-9]{2,20}$'::text)))) OR ((provider = 'wiclax'::text) AND ("eventId" IS NULL) AND (ctx IS NULL) AND ("sourceUrl" ~ '^https://\S+$'::text) AND ("categoryKeys" <> '{}'::jsonb)) OR ((provider = 'kbwb'::text) AND ("eventId" IS NULL) AND (ctx IS NULL) AND ("sourceUrl" IS NULL) AND ("categoryKeys" <> '{}'::jsonb) AND (NOT jsonb_path_exists("categoryKeys", '$.keyvalue()?((!(@."key" like_regex "^[1-9][0-9]{0,9}$") || @."value".type() != "string") || !(@."value" like_regex "^(ME|WE|MU|WU|MJ|WJ)$"))'::jsonpath))) OR ((provider = 'smartweb'::text) AND ("eventId" IS NULL) AND (ctx IS NULL) AND ("sourceUrl" ~ '^https://[a-z0-9.-]+/index\.php/smartweb/inscripciones/clasificacion/[1-9][0-9]*$'::text) AND ("categoryKeys" <> '{}'::jsonb) AND (NOT jsonb_path_exists("categoryKeys", '$.keyvalue()?(@."value".type() != "string" || !(@."value" like_regex "^(ME|WE|MU|WU|MJ|WJ)$"))'::jsonpath))) OR ((provider = 'golazo'::text) AND ("eventId" IS NULL) AND (ctx IS NULL) AND ("sourceUrl" ~ '^https://[a-z0-9.-]+/$'::text) AND ("categoryKeys" <> '{}'::jsonb) AND (NOT jsonb_path_exists("categoryKeys", '$.keyvalue()?((!(@."key" like_regex "^uitslagen-[a-z0-9-]+$") || @."value".type() != "string") || !(@."value" like_regex "^(ME|WE|MU|WU|MJ|WJ)$"))'::jsonpath))) OR ((provider = 'zone4'::text) AND ("eventId" IS NULL) AND (ctx IS NULL) AND ("sourceUrl" IS NULL) AND ("categoryKeys" <> '{}'::jsonb) AND (NOT jsonb_path_exists("categoryKeys", '$.keyvalue()?((!(@."key" like_regex "^[0-9]{4}-[0-9]{2}-[0-9]{2}/[0-9a-f]{8}/[^ ].*$") || @."value".type() != "string") || !(@."value" like_regex "^(ME|WE|MU|WU|MJ|WJ)$"))'::jsonpath))) OR ((provider = 'chronorace_xco'::text) AND ("eventId" IS NULL) AND (ctx ~ '^[0-9]{8}_[a-z0-9]{2,20}$'::text) AND ("sourceUrl" IS NULL) AND ("categoryKeys" = '{}'::jsonb)) OR ((provider = 'fotofiniss'::text) AND ("eventId" IS NULL) AND (ctx IS NULL) AND ("sourceUrl" ~ '^https://fotofiniss\.lv/sacensibas/[a-z0-9][a-z0-9-]*/rezultati$'::text) AND ("categoryKeys" <> '{}'::jsonb) AND (NOT jsonb_path_exists("categoryKeys", '$.keyvalue()?(@."value".type() != "string" || !(@."value" like_regex "^(ME|WE|MU|WU|MJ|WJ)$"))'::jsonpath))) OR ((provider = 'raceresult'::text) AND ("eventId" IS NULL) AND (ctx IS NULL) AND ("sourceUrl" ~ '^https://my\.raceresult\.com/[1-9][0-9]{3,9}/$'::text) AND ("categoryKeys" <> '{}'::jsonb) AND (NOT jsonb_path_exists("categoryKeys", '$.keyvalue()?((!(@."key" like_regex "^[1-9][0-9]{0,3}(/[1-9][0-9]{0,2})?$") || @."value".type() != "string") || !(@."value" like_regex "^(ME|WE|MU|WU|MJ|WJ)$"))'::jsonpath))) OR ((provider = 'eqtiming'::text) AND ("eventId" IS NULL) AND (ctx IS NULL) AND ("sourceUrl" ~ '^https://live\.eqtiming\.com/[1-9][0-9]{4,9}$'::text) AND ("categoryKeys" <> '{}'::jsonb) AND (NOT jsonb_path_exists("categoryKeys", '$.keyvalue()?((!(@."key" like_regex "^[^ ].{0,58}$") || @."value".type() != "string") || !(@."value" like_regex "^(ME|WE|MU|WU|MJ|WJ)$"))'::jsonpath)))));
